@push('scripts')<script>
(()=>{
 const checks=document.querySelectorAll('.return-check'),form=document.getElementById('return-form'),search=document.getElementById('exchange-search'),results=document.getElementById('exchange-results'),lines=document.getElementById('exchange-lines');let selected=[],timer;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>'₹'+Number(n||0).toFixed(2);
 checks.forEach(check=>check.addEventListener('change',()=>{const row=check.closest('tr');row.querySelectorAll('.return-quantity,input[type=hidden],.return-condition').forEach(input=>{input.disabled=!check.checked;if(check.checked&&input.classList.contains('return-quantity'))input.value=1})}));
 function render(){if(!selected.length){lines.innerHTML='<div class="empty-state compact"><div class="empty-icon">↔</div><b>No replacement selected</b><p>This will be processed as a refund unless you add replacements.</p></div>';return}lines.innerHTML=selected.map((p,i)=>`<div class="exchange-line"><span><b>${esc(p.name)}</b><small>${esc(p.sku)}${p.size||p.colour?' · '+esc([p.size,p.colour].filter(Boolean).join(' · ')):''} · ${money(p.price)}</small></span><label>Qty <input type="number" min="1" max="999" value="${p.quantity}" data-qty="${i}"></label><button type="button" class="remove-split" data-remove="${i}">×</button><input type="hidden" name="replacement_items[${i}][variant_id]" value="${p.id}"><input type="hidden" name="replacement_items[${i}][quantity]" value="${p.quantity}" data-hidden-qty="${i}"></div>`).join('')}
 search.addEventListener('input',()=>{clearTimeout(timer);const q=search.value.trim();if(!q){results.classList.add('hidden');return}timer=setTimeout(async()=>{try{const r=await fetch(`{{ route('products.search') }}?q=${encodeURIComponent(q)}`,{headers:{Accept:'application/json'}}),list=await r.json();results.dataset.items=JSON.stringify(list);results.innerHTML=list.length?list.map(p=>`<button class="search-result" type="button" data-add="${p.id}"><span><b>${esc(p.name)}</b><small>${esc(p.sku)}${p.size||p.colour?' · '+esc([p.size,p.colour].filter(Boolean).join(' · ')):''}</small></span><span><b>${money(p.price)}</b><small>${p.stock} in stock</small></span></button>`).join(''):'<div class="search-empty">No matching variant.</div>';results.classList.remove('hidden')}catch(e){results.innerHTML='<div class="search-empty">Search failed.</div>';results.classList.remove('hidden')}},180)});
 results.addEventListener('click',e=>{const button=e.target.closest('[data-add]');if(!button)return;const p=JSON.parse(results.dataset.items||'[]').find(v=>v.id==button.dataset.add);if(!p)return;const current=selected.find(v=>v.id===p.id);if(current)current.quantity++;else selected.push({...p,quantity:1});search.value='';results.classList.add('hidden');render()});
 lines.addEventListener('input',e=>{if(e.target.matches('[data-qty]')){const i=Number(e.target.dataset.qty);selected[i].quantity=Math.max(1,Number(e.target.value)||1);lines.querySelector(`[data-hidden-qty="${i}"]`).value=selected[i].quantity}});
 lines.addEventListener('click',e=>{const button=e.target.closest('[data-remove]');if(button){selected.splice(Number(button.dataset.remove),1);render()}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')results.classList.add('hidden')});
 form.addEventListener('submit',e=>{if(![...checks].some(x=>x.checked)){e.preventDefault();window.showToast('Select at least one item to return.')}});
})();
</script>@endpush
